Contract ManageSupplierCRUDService::createSupplier(id:Integer,name:String): Boolean {
          definition:
          obs:Supplier = Supplier.allInstance()->any(o | o.Id = id)

            precondition:
          (obs.oclIsUndefined() = true) or (obs.Name = name)

            postcondition:
          if obs.oclIsUndefined() = true then let newOb:Supplier in (newOb.oclIsNew()) and (newOb.Id = id) and (newOb.Name = name) else (obs.Id = id) and (obs.Name = name) endif and (result = true)

        }
